class Solution {
    struct DSU{
        vector<int> parent,rank;
        DSU(int n):parent(n),rank(n){
            iota(parent.begin(),parent.end(),0);
        }
        int find(int x){
            return parent[x]==x?x:parent[x]=find(parent[x]);
        }
        void unite(int a,int b){
            a=find(a);
            b=find(b);
            if(a==b)return;
            if(rank[a]<rank[b])swap(a,b);
            parent[b]=a;
            if(rank[a]==rank[b])++rank[a];
        }
    };
    public:int minimumHammingDistance(vector<int>& source,vector<int>& target,vector<vector<int>>& allowedSwaps){
        DSU dsu(source.size());
        unordered_map<int,unordered_map<int,int>> difference;
        for(auto& edge:allowedSwaps)dsu.unite(edge[0],edge[1]);
        for(int i=0;i<(int)source.size();++i){
            ++difference[dsu.find(i)][source[i]];
            --difference[dsu.find(i)][target[i]];
        }
        int answer=0;
        for(auto& [root,counts]:difference)for(auto [value,count]:counts)answer+=max(0,count);
        return answer;
    }
};
